/* Blurbs and details per map body, from the sourcebook (pp. 309-325).
 *
 * Generated by merge_translations.py — do not edit by hand.
 */

export const SOURCEBOOK = {
 "sys.brekk": {
  "blurb": {
   "sv": "Många anser att det här systemet är mer civiliserat än resten av Procyon, och här finns Hegemonins finare sidor — utbildning, konst och kultur. Rikedomen och kulturen gör att Legionen har en stark närvaro i sektorn. Men det finns gott om egendomliga hyperrymdsleder som inte sköts av Stjärnsmedsgillet och som böjer sig underligt, i långa öglor tvärs emot planeternas banor. Piloter kartlägger dessa så kallade ”mörka leder”, och den som är beredd att ta god tid på sig kan lätt gömma sig och undvika patruller.",
   "en": "Considered by many to be more civilized than the rest of Procyon, this system is home to many finer aspects of the Hegemony—education, art, and culture. Wealth and culture means the Legion presence is strong in the sector. However, there are many odd, non-Starsmithmaintained hyperspace lanes that bend strangely, making long loops perpendicular to planetary orbits. Pilots map these so-called “dark lanes,” making it easy to hide and dodge patrols if one is willing to take one’s time."
  }
 },
 "body.blackstarr": {
  "blurb": {
   "sv": "Nattmälarnas väldiga och till största delen tomma skepp där invigda tränar under sitt första år. Skeppet är släckt och flyttar sig regelbundet för att inte upptäckas. Det tar sällan emot besök, men undantag görs för dem som står på god fot med kulten.",
   "en": "The vast and largely empty Nightspeaker ship where initiates train for their first year. The ship is unlit and moves routinely to prevent discovery. It does not often receive visitors, but exceptions are made for those that have a favorable relationship to the Cult."
  }
 },
 "body.todav": {
  "blurb": {
   "sv": "Skymningens femte måne — utan atmosfär, full av kratrar och hem åt det uråldriga templet Dendara.",
   "en": "The fifth moon of Nightfall — airless, cratered, and home to the ancient temple of Dendara."
  },
  "details": {
   "sv": "Ett uråldrigt tempel på Skymningens femte måne, Todav. Vissa säger att det är ett Ur-tempel, andra att det är resterna av en bortglömd mystikerkult. Dess havererade korridorer är svåra att ta sig igenom eftersom månen saknar atmosfär och stör drivsystem och elektronik.",
   "en": "An ancient temple on Nightfall’s fifth moon, Todav. Some say it’s an Ur temple, others that it’s the remains of a forgotten mystic Cult. Its derelict corridors are tough to tour due to the moon’s lack of atmosphere and the glitching effect it has on drives and electronics."
  }
 },
 "body.brightwind": {
  "blurb": {
   "sv": "Ett stort gasmoln som stjärnan kastat ut, numera använt som racerbana av Ekovågsryttarna. Trots att det är både dödligt och olagligt tävlar förare från hela sektorn om pengar och ryktbarhet. Inbjudningarna till loppen är exklusiva och kräver att man kvalificerar sig under lika livsfarliga förhållanden.",
   "en": "A large gas cloud ejected by the star, now used as racing grounds by the Echo Wave Riders. Despite it being both lethal and illegal, racers from all over the sector compete for cred and fame. Invitations to the races are exclusive and require qualifying in equally hazardous conditions."
  }
 },
 "body.isotropa": {
  "blurb": {
   "sv": "Isotropa går i bana nära stjärnan och är Procyons ökändaste fängelse. Fångvaktarna förmedlar möten med fångarna och delar ut strafflindringar åt de mäktiga och rika. De lyder under Malklä, men fängelset sköter till stor del sig självt.",
   "en": "Orbiting near the star, Isotropa is the most notorious prison in Procyon. Wardens broker audiences with prisoners and grant commutations for the powerful and wealthy. They report to Malklaith but the prison largely runs itself."
  }
 },
 "sys.holt": {
  "blurb": {
   "sv": "Holt var det andra systemet i Procyon som koloniserades, även om porten mellan Rin och Holt var besvärlig att stabilisera. Till slut hittade hegemoniska forskare en rad Ur-nycklar i systemet som tvingade porten att alltid leda till Holt. Porten är dock fortfarande nyckfull och har varit känd för att öppna sig av egen kraft. Inga skepp har kommit igenom vid dessa spontana öppningar — än så länge. Holtsystemets stjärna brinner vit, men den är långt äldre än stjärnor av den typen borde vara, något som hegemoniska forskare tillskriver uråldrig Ur-manipulation.",
   "en": "Holt was the second Procyon system to be colonized, though the Rin-Holt gate was troublesome to stabilize. Hegemonic scientists eventually found a series of Ur keys in the system that forced the gate to consistently lead to Holt. The gate remains temperamental, however, and has been known to open on its own. No ships have come through during these spontaneous openings—so far. The Holt system star burns white, though it is far older than stars of this type should be, which Hegemonic scientists attribute to ancient Ur manipulation."
  }
 },
 "body.jerec": {
  "blurb": {
   "sv": "En fritt svävande klump av skepp och delar, hopkopplad med magnetism och kablar. Söker du utrustning billigt är Jerrys skrot rätt ställe, även om det troligen saknas en bit eller inte går att lita på. Jerry köper också, men han är en slug prutare.",
   "en": "A free-floating mass of ships and parts, connected via magnetism and cabling. If you’re looking for equipment on the cheap, the Junkyard is your place, though it will likely be missing a piece or unreliable. Jerec also buys, but is a canny haggler."
  }
 },
 "body.auto4": {
  "blurb": {
   "sv": "Gillet satte upp en automatiserad plattform för bränsleförsäljning, täckt av försvarssystem som ska avskräcka från stöld. Just därför förhandlar en del parter här, för att hålla nere risken att det trappas upp. Ingen vet vad som hände med de tre första plattformarna.",
   "en": "The Guild set up an automated platform for selling fuel, covered in defensive systems to deter theft. Because of this, some parties conduct negotiations here to discourage escalation. Nobody knows what happened to the first three platforms."
  }
 },
 "body.omega": {
  "blurb": {
   "sv": "Tre kartläggningsbesättningar och en militär expedition försvann innan Legionen satte planeten i karantän. Den vimlar av en dödlig livsform som bygger bo inne i Ur-ruiner och överlever kärnvapen från omloppsbana. Hegemonin betraktar den som fientlig, men betydelselös för sina planer.",
   "en": "Three survey crews and one military expedition vanished before the Legion quarantined this planet. It’s overrun by a deadly life form that nests withing Ur ruins and can resist nukes from orbit. The Hegemony considers it hostile, but insignificant to its plans."
  }
 },
 "sys.iota": {
  "blurb": {
   "sv": "Planeterna i Iota kretsar kring ett stjärnpar — en gul sol (Iota-1) och en brun dvärg (Iota-2). När Hegemonin väl anlände fanns här två asteroidbälten, och i det ena ligger fortfarande en stor del av en sönderslagen planet kvar. Bägge bältena har uppenbart varit planeter en gång i tiden, men ingen vet vilken katastrof som slog dem i stycken. Som gillena har för vana skådade de inte given häst i munnen — de anlade Iotas skeppsvarv, som med metaller från bältena servar en stor del av sektorns skepp.",
   "en": "The planets in Iota orbit a pair of stars—a yellow sun (Iota-1) and a brown dwarf (Iota-2). By the time the Hegemony arrived, there were two asteroid belts, one of which still has a large portion of a shattered planet remaining in its midst. Although both the belts were clearly planets once upon a time, nobody is sure what sort of calamity shattered them. As is their wont, the Guilds didn’t look a gift horse in the mouth—they set up the Iota shipyards, which service many ships in the sector using metals from the belts."
  }
 },
 "body.shipyards": {
  "blurb": {
   "sv": "Huvudvarvet drivs av Stjärnsmederna, men många mindre, licensierade verkstäder sköter reparationer och ombyggnader. Stationerna är fulla av uttråkade rymdfarare som söker vad som helst att fördriva väntan med. Ibland värvar Stjärnsmederna dumdristiga piloter till prototyptester.",
   "en": "While the primary yard is run by Starsmiths, many smaller, licensed hubs work on repairs and ship refits. These stations are full of bored spacers looking for any distraction from the wait. Starsmiths sometimes hire foolhardy pilots for prototype tests."
  }
 },
 "body.zx1138": {
  "blurb": {
   "sv": "En komet med lång omloppstid har nyligen vikit av från sin bana och kommit långt närmare Indri. Varför den bytt kurs är oklart, men lokalbefolkningen har bett guvernören utreda saken. Mystiker hävdar att det förskjutit systemets Strålådror, så att Ådern ibland beter sig oberäkneligt.",
   "en": "A long-period comet has recently diverged from its course, taking it much closer to Indri. Reasons for the course change are unclear, but locals have requested the Governor investigate. Mystics claim that this has shifted the system Way lines, making the Way sometimes act unpredictably."
  }
 },
 "sys.rin": {
  "blurb": {
   "sv": "Rin är inkörsporten till Procyonsektorn och koloniserades för drygt hundra år sedan av Hus Nim-Amar. Systemet har aldrig varit viktigt, så Malklä har aldrig satsat mer än ett minimum av resurser på att utveckla det. I stället används det för att skola unga husmedlemmar, eller som en straffplacering för dem som svikit huset. Galaktisk lag märks mer här än i resten av sektorn, eftersom sektorns förvaltning har sitt säte här och systemet rymmer portar till tre andra system, däribland en väg mot resten av Hegemonin.",
   "en": "The entry point to the Procyon sector, Rin was colonized a little over a hundred years ago by House Nim-Amar. It has never been an important sector, so Malklaith’s never invested more than a minimum of resources in its development. Instead, it’s used to train young House members, or as an assignment to punish those who fail the House. Galactic law is more present here than the rest of the sector, as this is the seat of the sector’s administration and contains gates to three systems, including a path towards the rest of the Hegemony."
  }
 },
 "body.aleph": {
  "blurb": {
   "sv": "Med sina giftiga gaser och sin tektoniska instabilitet vore Aleph en planet att hålla sig undan från, om det inte vore för mineralfyndigheterna. Det mesta av rikedomen som grävs upp beskattas hårt av guvernören, vilket ständigt leder till oro bland gruvarbetarna.",
   "en": "Between the poisonous gases and tectonic instability, Aleph would be a planet to avoid if it weren’t for its mineral stores. Most of the wealth dug from the planet is taxed heavily by the Governor, leading to frequent unrest with the miners."
  }
 },
 "body.ashtari": {
  "blurb": {
   "sv": "En uråldrig, skadad rest av ett väldigt Ur-skepp ligger i rymden och alstrar en nebulosa inne i systemet. Där inne fungerar vanlig framdrivning knappt och navigationssystemen är opålitliga. Malströms pirater listade ut hur man navigerar molnet och lade sin bas under dess skyddande slöja.",
   "en": "An ancient damaged remnant of a massive Ur ship lies in space, generating an in-system nebula. Within it, normal propulsion is minimal and nav systems dodgy. The Maelstrom pirates figured out how to navigate the cloud, and made their base of operations within its protective shroud."
  }
 },
 "body.straylight": {
  "blurb": {
   "sv": "Senaste modeflugan: Irrblosset är en påkostad klubb och cocktailbar där eliten kan äta och dricka gott. Den ligger oftast i bana runt Aleph, men kan flytta sig till andra planeter och månar i systemet. Ägaren Chance håller hårt i tyglarna, men ibland spårar det ändå ur.",
   "en": "The latest fad, the Straylight is an upscale club and cocktail bar where elites can wine and dine. It usually orbits Aleph, though it can move to other planets and moons in the system. Its owner, Chance, runs a tight establishment, but things can sometimes get out of hand."
  }
 },
 "body.baftoma": {
  "blurb": {
   "sv": "Hegemonin utvinner resurser till sista droppen, och planeter som inte kan bära liv skalas in till kärnan. Baftoma var en gång en sådan planet — nu återstår bara en byggnadsställning av sten, och den söndertrasade formen används bara av folk som gömmer sig eller skakar av sig förföljare.",
   "en": "Resource exploitation by the Hegemony is comprehensive, and planets incapable of sustaining life are stripped to the core. Baftoma was once such a planet—now only scaffolding of rock remains, its broken form only used by folks hiding or dodging pursuit."
  }
 },
 "body.vet": {
  "blurb": {
   "sv": "En gasjätte med ringar. Inga månar; den gillekontrollerade stationen SB-176 håller dess omloppsbana.",
   "en": "A gas giant with rings. No moons; the Guild-controlled station SB-176 holds its orbit."
  }
 },
 "body.aketi": {
  "blurb": {
   "sv": "Tungt beväpnade vakter som patrullerar de höga murarna kring Baslägret Ett och kastar nervösa blickar mot djungeln. Forskarlag som packar inför nästa expedition, mitt emot tjuvjägare som gör detsamma. En smugglare som gör upp om villkoren med en kund i ett tält medan en privat barista blandar drinkar åt dem.",
   "en": "Heavily armed guards patrolling the tall walls of Base Camp One, nervously eyeing the jungle. Research crews packing for their next expedition across from poachers doing the same. A smuggler discussing arrangements with a client in a tent while a personal barista makes them drinks."
  },
  "details": {
   "sv": "Den här grönskande djungelvärlden hade varit långt mer bebodd om inte naturlivet varit så obeskrivligt fientligt. Mellan snabbväxande köttätande växter, best som går bärsärk med årstiderna och hyperaggressiv fisk är det bara några få sorter som besöker Aketi — forskare, tjuvjägare och brottslingar som gömmer sig för lagen. Planeten är stämplad som ett ”naturreservat” under Malklä.\n\n**Anmärkningsvärda personer**\n\n- **Rakkniv** — En jägare som rustar en expedition för att fånga den dödliga Stora Phereniki åt en rik uppdragsgivare. (kallsinnig, erfaren, spelgalen)\n- **Zokar Pava** — Förlorad legionär som handlar med vapen av militär kvalitet. (försiktig, minutiös, dissident)\n- **Intal Brel** — Konkordiatriddare med psyklinga. Reser med en niofot lång xeno, en avfallen präst och en Ur-bot. Förlorade nyligen en i sällskapet och hoppas hitta en ersättare. (religiös, vaksam, hedersam)\n- **Asha Ravann** — Befälhavare för Baslägret Ett. Införde de murmonterade eldkastarna som håller djungeln på avstånd. (trött, luttrad, obeveklig)",
   "en": "This verdant jungle world would be more settled, were it not for the incredibly hostile natural life. Between rapidly spreading carnivorous plants, seasonally rampaging beasts, and hyper-aggressive fish, only a few distinct types visit Aketi— researchers, poachers, and criminals hiding from the law. The planet is labeled a Malklaith “nature preserve.”\n\n**Notables**\n\n- **Razor** — A hunter mounting an expedition to catch the deadly Grand Phereniki for a rich client. (callous, experienced, gambler)\n- **Zokar Pava** — Lost Legionnaire dealing in military-grade weapons. (cautious, meticulous, dissident)\n- **Intal Brel** — Psy-blade-wielding Concordiat Knight. Travels with a nine-foot-tall xeno, an ex-priest, and an Urbot. Recently lost a party member and hopes to replace them. (religious, vigilant, honorable)\n- **Asha Ravann** — Base Camp One commander. Instituted a wallmounted flamethrower measure that’s kept the jungle at bay. (tired, jaded, relentless)"
  }
 },
 "body.amerath": {
  "blurb": {
   "sv": "Väldiga, människostora blommor som slår ut längs en rankburen stig genom träden. Sötaktig honungsdoft i luften. Forskare som äter lunch på kaféer i trädkronorna medan de går igenom projektplaner. Sjuka pilgrimer som ber om bot i väntan på färden till det gamla Tiggarordenstemplet djupt inne i skogarna.",
   "en": "Massive, person-sized flowers blooming along a vinesupported path through the trees. The sweet smell of honey in the air. Scientists having lunch at treetop cafés while reviewing project schedules. Sick pilgrims praying for a cure while waiting to travel to the old Mendicant temple deep in the forests."
  },
  "details": {
   "sv": "Med sin frodiga biom har planeten blivit känd för läkemedelsforskning och läkemedelstillverkning. Stora delar av planeten sköts väl om, och tack vare gillets omsorger står trädgårdsstaden Rost i blom året runt. Varma, milda regn faller ofta. De djupa skogarna döljer både piratnästen och tiggarordenstempel bland överväxta ruiner.\n\n**Anmärkningsvärda personer**\n\n- **Yon Lirak** — Knarklangare i det övre skiktet. Driver en fabrik i Rost som aldrig stänger och som tillverkar syntetiska narkotika åt flera av de stora arterna. (erfaren, hänsynslös, oförsonlig)\n- **Ara Blaze** — En gång stjärnidrottare, numera den främsta gropkämpen i de underjordiska fightklubbarna. Ara har provat varje prestationshöjande preparat hon blivit erbjuden, och det har förändrat henne. (hänsynslös, oförsonlig, konstruerad)\n- **Uyen al’Vorron** — Berömd adlig duellant från det religiösa Hus Vorron. Söker en växt att odla i den nya vingård han planerar på en måne nära Kärnan. (beväpnad, dödlig, uppmärksam)",
   "en": "With a lush biome, this planet has become well known for pharmaceuticals research and manufacturing. Many regions of the planet are well tended, and due to the comprehensive attentions of the Guild, the garden city of Rost is in perennial bloom. Warm, gentle rains come frequently. The deep forests hide some pirate lairs and Mendicant temples amid overgrown ruins.\n\n**Notables**\n\n- **Yon Lirak** — High-end drug dealer. Runs a factory in Rost that never shuts down, producing synthetic narcotics for several major species. (experienced, ruthless, unforgiving)\n- **Ara Blaze** — Once a star athlete, now a preeminent pit fighter in the underground fight clubs. Ara has tried every performanceenhancing drug offered to her, and it has changed her. (ruthless, unforgiving, engineered)\n- **Uyen al’Vorron** — Famous Noble duelist from the religious House Vorron. Seeking to cultivate a plant for the new vineyard he’s planning to grow on a moon near the Core. (armed, deadly, observant)"
  }
 },
 "body.indri": {
  "blurb": {
   "sv": "Svävarbilstrafik som speglar reklamen på husväggarna. Gasmaskförsedda fotgängare som hastar fram på trottoarer av metall under paraplyer preparerade mot surt regn. Långsamma containrar på väg mot lagerhusen. Åskmoln med blixtar i alla kulörer som rullar in.",
   "en": "Hovercar traffic reflecting adverts on buildings. Gasmasked pedestrians walking hurriedly down metal sidewalks with umbrellas treated to prevent acid rain damage. Slow-moving containers being shuttled to warehouses. Storm clouds with multi-hued lightning rolling in. -"
  },
  "details": {
   "sv": "Över 25 procent av allt gods som tillverkas i Procyonsektorn kommer från den här oerhört industrialiserade planeten. Tjocka, rostfärgade moln gör det skymningsmörkt även mitt på dagen. Från rymdhamnen Reves, omgiven av lagerhus, kan man se den mäktiga siluetten av skorstenar och lågor från gasfacklor. Att röra sig ute utan skyddsutrustning avråds bestämt.\n\n**Anmärkningsvärda personer**\n\n- **Piro Locke** — Äger ett antal diskreta, välbevakade förråd i omloppsbana och tillämpar en strikt policy om att inga frågor ställs. Är det olagligt så förvarar Locke det. (hedersam, förmögen, självsäker)\n- **Zo O Yun Ta Ri** — Xenovapenhandlare känd för prototyper och specialbeväpning. Har nyligen kommit över ett skeppsvapen av Ur och tänker auktionera ut det i skydd av en storm. (xeno, kontaktrik, försiktig, minutiös)\n- **Pasha ”Roc” Lensarr** — Askknivarnas lokala överhuvud. Känd för sin brutala syn på hur brottslighet ska organiseras. Bär skräddarsydda kostymer som låter vingarna vecklas ut vid behov. (xeno, vildsint, hänsynslös, krävande)",
   "en": "Over 25 percent of all goods manufactured in the Procyon Sector come from this incredibly industrialized planet. Thick, rust-colored clouds create dusk even during the day. From the warehouse-surrounded spaceport of Reves, one can view the impressive skyline of smokestacks and flames from gas burn-offs. Travel without protective gear is not advised. r u l e : The factories have caused massive air pollution; anyone spending any amount of time outside without proper equipment or xeno abilities gains level 2 harm “Indri Lung.”\n\n**Notables**\n\n- **Piro Locke** — Owns a number of discreet, well-guarded storage spaces in orbit, and has a strict no-questions policy. If it’s illegal, it’s certainly stored by Locke. (honorable, wealthy, confident)\n- **Zo O Yun Ta Ri** — Xeno weapons dealer known for prototypes and specialty armaments. Recently acquired an Ur ship weapon and plans to auction it under the cover of a storm. (xeno, connected, cautious, meticulous)\n- **Pasha “the Roc” Lensarr** — Local head Ashen Knife. Known for a brutal approach to criminal organization. Wears customtailored suits that allow his wings to unfurl as needed. (xeno, fierce, ruthless, demanding)"
  }
 },
 "body.lithios": {
  "blurb": {
   "sv": "Ett lila och grönt norrsken över en iskall himmel. Isutforskare som viskar om Yarus yngelkammare. Uppvärmd ånga som väller ut kring Kolonin Enslighet. Kolonister i heltäckande parkas till häst på stora, mångögda hunddjur. Bönder som drar lådor med gasålar och issvampsvin i seglande snöskrapor.",
   "en": "A purple and green aurora shining over the freezing cold sky. Ice explorers whispering about the Yaru creche. Heated vapors escaping around Solitude Colony. Colonists in full parkas, riding large, many-eyed canids. Farmers pulling gas-eels and ice-mushroom wine crates in sail-sporting snow skimmers."
  },
  "details": {
   "sv": "Uråldriga ispalats sticker upp här och var på den frusna planetens yta, men folket som byggde dem är sedan länge borta. Tillträdet till palatsen har begränsats efter en rad mystiska dödsfall bland utforskare. Speglar i omloppsbana lyser som konstgjorda solar, håller några av de större bosättningarna varma och driver stora borriggar som utvinner vatten och kondenserade gaser.\n\n**Anmärkningsvärda personer**\n\n- **Asha Munzen** — Guvernörens forna älskarinna, isklättrare, mystiker och utforskare av ispalatsen och gasgrottorna. Kommer bara tillbaka med syner, aldrig med artefakter. Försöker finna ”Det första budskapet”. (mystisk, ärelysten, vältränad)\n- **Ren Larana** — Xenobiolog som försöker återuppväcka en uråldrig xeno som hittats infrusen men vid liv i isen, trots att hegemonisk lag förbjuder det. Försöker just nu smuggla ut xenon från planeten. (djärv, briljant, självsäker)\n- **Raf Urich** — Ispirat, för närvarande strandsatt på planeten. Använde skeppets vapen för att skära ut en kajplats i isen. Har hållit sig undan och stulit delar för att laga skeppet. (erfaren, försiktig, slug)",
   "en": "Ancient ice palaces dot the surface of this frozen planet, but the race to which they belong has long since passed. Entry to the palaces has been restricted after a string of mysterious explorer deaths. Orbital mirrors shine like artificial suns, keeping a few larger settlements warm and powering large mining rigs for extracting water and liquefied gases.\n\n**Notables**\n\n- **Asha Munzen** — Ex-lover of the Governor, ice climber, mystic, and explorer of the ice palaces and gas caves. Only returns with visions, never artifacts. Attempting to find the “First Message.” (mystic, ambitious, fit)\n- **Ren Larana** — Xenobiologist attempting to revive an ancient xeno found frozen but alive in the ice, despite Hegemonic law forbidding it. Currently trying to sneak the xeno off-world. (bold, brilliant, confident)\n- **Raf Urich** — Ice pirate, currently stranded on planet. Used his ship weapons to cut a berth in the ice. Has been hiding out, stealing parts to repair his ship. (experienced, cautious, shrewd)"
  }
 },
 "body.mem": {
  "blurb": {
   "sv": "Hegemoniska tjänstemän med skärp som samtalar med memiska arbetsledare. Genomskinliga spiror som reser sig från regeringspalatset under vattnet upp till paviljonger under bar himmel. Turister som går ombord på ubåtar för att titta på havslivet. Forskare i exodräkter på djuphavsuppdrag medan memierna ser på från vattnet.",
   "en": "Hegemonic officials in sashes, talking with Memish labor bosses. See-through spires rising from the underwater government palace to open-air pavilions. Tourists embarking on submersibles to take in the local sea life. Scientists in exo-suits on deep-sea missions while the Memish watch from the waters."
  },
  "details": {
   "sv": "Den här havsplaneten hade koloniserats av Hegemonin i nästan hundra år innan de akvatiska xenosarna gav sig till känna — och gjorde anspråk på planeten. Hegemoniska styrkor krossade den memiska krigsmakten och inlemmade memierna i Hegemonin. Att utforska Mem har visat sig svårt på grund av de fristående gravitationsbrunnarna djupt under vågorna.\n\n**Anmärkningsvärda personer**\n\n- **Victor Kromyl** — Planetguvernör. Söker bevis för memiskt uppror sedan ett par underlydande försvunnit. Aldrig utan sin legionära livvakt. (vaksam, minutiös, paranoid)\n- **Espa Nur** — Memisk arbetsledare. Hans ärr är fyllda med djuphavets självlysande liv. Rapporterar till Kromyl om uppviglande beteende, men döljer vad han vet om memisk ockultism. (xeno, ärelysten, listig, förrädisk)\n- **Wyndam Taru Zahn** — Biologiforskare som söker ett samband mellan memierna och planetens övriga liv, med klen framgång. Sätter samman en expedition till den uråldriga memiska staden Bok-Dar. (förmögen, briljant, hängiven)",
   "en": "This ocean planet was colonized by the Hegemony for almost a hundred years before aquatic xenos made themselves (and their planetary claims) known. Hegemonic forces broke the Memish military and incorporated them into the Hegemony. Exploration of Mem has proven difficult because of the free-standing gravity wells deep beneath the waves.\n\n**Notables**\n\n- **Victor Kromyl** — Planetary Governor. Seeks proof of Memish rebellion after a few subordinates vanished. Always with his Legion bodyguard. (vigilant, meticulous, paranoid)\n- **Espa Nur** — Memish labor boss. His scars are packed with deepocean bioluminescence. Reports to Kromyl on seditious behavior, but hides his knowledge of Memish occultism. (xeno, ambitious, cunning, treacherous)\n- **Wyndam Taru Zahn** — Biology researcher seeking a connection between the Mem and other planetary life, with little success. Gathering an exploration of the ancient Mem city of Bok-Dar. (wealthy, brilliant, passionate)"
  }
 },
 "body.nightfall": {
  "blurb": {
   "sv": "Höghus som tänds kvarter för kvarter när staden går från dag till natt på några minuter. En stökig nattklubb som spyr ut dansande i svarta dräkter med lysande detaljer på en solbelyst gata. Det blå skenet från en publik datakiosk som projicerar morgondagens nattschema och marknadsrörelser.",
   "en": "High-rises lighting up block by block as the city goes from day to night in the span of minutes. A rowdy night club spilling dancers clad in black, glow-accented outfits onto a sun-lit street. The blue glow of a public data kiosk projecting tomorrow’s night schedule and market changes."
  },
  "details": {
   "sv": "Uppkallad efter de täta förmörkelser som planetens 13 månar orsakar. Deras nyckfulla banor gör natten förutsägbar bara med dator. Staden Yaw ligger där natt och dag varar mellan 2 och 12 timmar var. Den sjuder av ekonomisk aktivitet och är ett vanligt resmål för turister och handelsmän. Känd för sitt förnäma kök och sin teater.\n\n**Anmärkningsvärda personer**\n\n- **Saren Galia** — Informationsmäklare och vadhållare. När du inte kan betala dina skulder blir du hennes informatör. (paranoid, snabb, kontaktrik)\n- **Lotus** — Modeikon och smakdomare, klädd i utstuderade kreationer. I hemlighet en fixare med stort inflytande. Har varit känd för att ta välgörenhetsuppdrag när saken tilltalar henne. (populär, hängiven, minutiös)\n- **Jet Wolffe** — Lönnmördare ur Scharlakansvargarna. Kan hyras för rätt pris, men tar bara uppdrag utanför planeten. Reser med ett stort, blåhudat främmande djur av okänt ursprung. (reserverad, självsäker, oförsonlig)\n- **Sol Brighton** — Sektorns bästa advokat. (listig, kontaktrik, dyr)",
   "en": "Named for frequent eclipses caused by the planet’s 13 moons. Their erratic movements make night only predictable by computer. The city of Yaw is nestled where night and day last between 2 and 12 hours each. It bustles with economic activity and is a frequent destination for tourists and traders. Known for its haute cuisine and theater.\n\n**Notables**\n\n- **Saren Galia** — Data broker and bookie. When you can’t pay your debts, you become her informant. (paranoid, fast, connected)\n- **Lotus** — Fashionista and tastemaker, dressed in elaborate costumes. Secretly a highpowered fixer. Has been known to take charity cases when the cause appeals to her. (popular, passionate, meticulous)\n- **Jet Wolffe** — Scarlet Wolf Assassin. Can be hired at a price, but only takes off-world jobs. Travels with a large, blue-skinned alien animal of unknown origin. (aloof, confident, unforgiving)\n- **Sol Brighton** — Best lawyer in the sector. (cunning, connected, expensive)"
  }
 },
 "body.sb176": {
  "blurb": {
   "sv": "Kalla, klapprande steg över den skinande rena huvudgatan. Viskningar från politikerbroderiet som dricker te i en salong. Barn som springer skrattande genom korridorerna. Generatorernas brum i de mörklagda sidogångarna ned mot de undre nivåerna. Sotiga arbetare som ryter åt varandra i gruvriggarnas trånga utrymmen.",
   "en": "Cold clacking of footsteps on the brilliantly clean main concourse. Whispers of politicos taking tea at a parlor. Children running down halls, laughing. The hum of generators in the darkened side passages leading to the lower levels. Dingy workers shouting in the cramped quarters of the mining rigs."
  },
  "details": {
   "sv": "Man behöver ingen planet för att bryta malm. Eller åtminstone ingen mark. Den här kombinationen av ”gruv”-plattform och rymdkoloni står för utvinningen av resurser ur Vet, gasjätten nedanför. Gruvriggarna i himlarna där nere — mestadels bemannade av Ur-botar — skickar upp sitt gods till det här navet. Det mesta paketeras och skjuts iväg mot Rin-Ecliptis-porten.\n\n**Anmärkningsvärda personer**\n\n- **Yast Jor** — Gillets chef för utposten. Jor är känd för att få saker gjorda, även när det kräver att reglerna böjs. Han är adrenalinjägare och håller sig med ett racerskepp uppgraderat av gillet för de sällsynta lediga dagarna. (befallande, slug, djärv)\n- **Kasumi Ortcutt** — En mystiker som påstår sig höra Vets röst, gasjätten plattformen bryter ur. Handlar med information, däribland esoterika om Ur. (lidelsefull, underlig, religiös)\n- **Espa ”bult” Wu** — Fackligt ombud för gillets gruvarbetare. Uppviglare, älskad av arbetarna. Har suttit inne otaliga gånger för brott både verkliga och påhittade. (populär, upprorisk, ärelysten)",
   "en": "You don’t need a planet in order to mine. Or at least, you don’t need ground. This combination “mining” platform and space colony is responsible for extracting resources from Vet, the gas planet below. The mining rigs in the skies below—mostly manned by Urbots—send their goods to this central hub. Most of those are packaged and fired towards the Rin-Ecliptis gate.\n\n**Notables**\n\n- **Yast Jor** — Guilder head of the outpost. Jor is known for getting things done, even if it means bending the rules. A thrill-seeker, he keeps a Guild-enhanced racing ship for rare days off. (commanding, shrewd, bold)\n- **Kasumi Ortcutt** — A mystic who claims to hear the voice of Vet, the gas giant the platform is mining. Trades information, including esoterica on the Ur. (passionate, strange, religious)\n- **Espa “bolt” Wu** — Labor organizer for the Guild miners. Rabblerouser beloved by the workers. Has been incarcerated numerous times for crimes both real and fabricated. (popular, dissident, ambitious)"
  }
 },
 "body.shimaya": {
  "blurb": {
   "sv": "Professorer som vandrar längs Akademins marmorstigar. En marknadsgata där påstridiga försäljare langar sandmaskspett till hungriga gruvarbetare. Grävlag som packar febrilt ombord på sandskiffar, redo att slå mynt av en fyndighet som stormen blottat. Stormlarmet som tjuter över hela staden.",
   "en": "Professors walking down the marble paths of the Academy. A market street with insistent vendors selling sandworm kebabs to hungry miners. Excavators packing furiously onto sand-skiffs, ready to take advantage of a stormcleared deposit. The storm alert blaring citywide."
  },
  "details": {
   "sv": "Den här ökenplaneten härjas av elektriska stormar som ibland blåser bort den färgade sanden från mineralfyndigheter som är livsviktiga för rymdfart — eller förvandlar sanden till glas så att man ser ned i ruinerna under. Lagen kappas om att hinna först. Här finns en betydande civilbefolkning och dessutom sektorns främsta lärosäte, Khalud-akademin.\n\n**Anmärkningsvärda personer**\n\n- **Hondo Suzuka** — HNN-reporter som letar bevis för en konspiration vid Khalud-akademin, där flera toppstudenter har försvunnit. (ärelysten, vaksam, charmerande)\n- **Ed Ursis** — Gilleingenjör som sköter omloppsanläggningen och de elektrostatiska generatorer den driver för att hålla stormarna borta från huvudstaden. Samlar på statyetter i färgat glas. (hängiven, briljant, överarbetad)\n- **Miranda Kasur** — Mineralhandlare med ett lass stöldgods hon måste bli av med. Håller sig undan sedan hennes första affär gick snett. (skräckslagen, listig, stolt)\n- **Sahar** — Mystiker i sällsam dräkt som lever ute i öknen. (besynnerlig, blåögd, uråldrig)",
   "en": "This desert planet is ravaged by electrical storms that occasionally clear colored sand off mineral deposits essential to space travel, or turn it to glass, giving a view to the ruins beneath. Teams race to capitalize on these events. There is a substantial civilian population, including the sector’s preeminent educational institution, Khalud Academy.\n\n**Notables**\n\n- **Hondo Suzuka** — HNN reporter seeking evidence of conspiracy at Khalud Academy, where several top students have vanished. (ambitious, vigilant, charming)\n- **Ed Ursis** — Guild Engineer that works on the orbital array and the electrostatic generators it powers to keep the storms away from the capital. Collects colored glass statues. (dedicated, brilliant, overworked)\n- **Miranda Kasur** — Minerals trader with a load of stolen goods she needs to move. In hiding after her first deal went wrong. (scared, cunning, proud)\n- **Sahar** — Strange-suited mystic that lives in the desert. (odd, blue-eyed, ancient)"
  }
 },
 "body.sonhandra": {
  "blurb": {
   "sv": "Evig skymning över asfalterade gator och betongbyggnader. Tjutet från de täta vindstormarna mellan de två regionerna. Maskerade och kåpklädda främlingar som samlas kring ett stållager innan auktionen börjar. Rad efter rad av skepp parkerade på öppen jord i Ugars utkanter.",
   "en": "Perpetual twilight amid paved streets and concrete buildings. Howling of frequent wind storms between the two regions. Masked and cloaked strangers congregating around a steel warehouse before an auction begins. Row after row of ships parked in the open dirt on the outskirts of Ugar. A"
  },
  "details": {
   "sv": "Den här planeten är bunden i sin rotation — samma sida vänds ständigt mot stjärnan. Dagsidan är brännhet. Egendomligt nog slocknar alla ljuskällor omkring en kilometer in på nattsidan. De flesta bosättningarna ligger i gränszonen i skymningen, däribland huvudstaden Ugar. Planeten är känd för sina släpphänta handelsregler och har blivit ett självklart mål för smugglare och hälare.\n\n**Anmärkningsvärda personer**\n\n- **Del Hex** — Fredlös revolverman. Bär tydliga cybernetiska implantat från sin tid i gillet. Efterlyst i flera system. Driver en fightingklubb med vibrovapen djupt inne på dagsidan. (skoningslös, snabb, försiktig)\n- **Abra Drake** — Fixare och auktionsutropare. Kan hon inte få tag på det eller sälja det så känner hon någon som kan. (välkontaktad, självsäker, djärv)\n- **Zeed ”tank” Marak** — Legosoldat som blivit nyctodlare. Vet var och hur man gömmer skepp på nattsidan. (spelgalen, befallande, luttrad)\n- **Osha** — Nyctrökande, grovhuggen före detta legionär. Driver Tre solar, en spelhåla och traktens största sylta. (dödlig, pensionerad, hårdför)",
   "en": "This planet is tidally locked—the same side of the planet faces the star at all times. The day side is blistering. Oddly, all light sources extinguish about a kilometer into the night side. Most of the settlements are in the twilight border zone, including the capital of Ugar. Known for its lax policies regulating trade, it’s become a choice destination for smugglers and fences alike.\n\n**Notables**\n\n- **Del Hex** — Outlaw gunslinger. Has some obvious cybernetics from his Guild days. Wanted in several systems. Runs a vibro-weapon fighting ring deep in the day side. (ruthless, fast, cautious)\n- **Abra Drake** — Fixer for hire and auctioneer. If she can’t get it or sell it, she knows someone who can. (connected, confident, bold)\n- **Zeed “tank” Marak** — Mercenary turned Nyct farmer. Knows where and how to hide ships on the night side. (gambler, commanding, experienced)\n- **Osha** — Nyct-smoking, grizzled ex-Legionnaire. Runs the Three Suns, a gambling den and the biggest local dive. (deadly, retired, steely)"
  }
 },
 "body.the-cove": {
  "blurb": {
   "sv": "Snabba vad som slås om ett öppet slagsmål mellan två kaptener som förolämpat varandra. Blåvita gnistor när underhållsarbetare svetsar på ett nytt skepp. Färskvatten som dimmar ned rad på rad av hydroponik. En sändning över hela stationen om Banshees senaste byte, följd av jubel genom korridorerna.",
   "en": "Quick bets taken on an open brawl between two captains over slights. Bluewhite sparks of maintenance workers welding on a new ship. Fresh water misting over rows of hydroponics. A station-wide broadcast of the Banshee’s latest conquest, followed by cheers throughout the halls."
  },
  "details": {
   "sv": "Malströmspiraterna har byggt en station av havererade fraktskepp, lastcontainrar och stulen skrotmetall. Det här hemmet kallar de Lyan. Företagsamma själar kan ta reda på var den ligger om de har envisheten eller kontakterna — även om den flyttar sig inom Ashtarimolnet. Bara piraternas allra bästa vänner kan få stormdrifter för att navigera bättre.\n\n**Anmärkningsvärda personer**\n\n- **Ryle** — En gestalt större än livet med hat mot Hegemonin. Hon är tuff och våldsam och tvingar på en piratkodex på dem som vill följa henne. Lämnade en gång sin förstestyrman att dö på en kal värld efter ett myteri. (stolt, krävande, hedersam)\n- **Praxis Ivanov** — Köpman som alltid är beredd att göra upp. Hans tentakler är tatuerade med berättelsen om hans flerahundraåriga liv. (xenos, luttrad, slug, älskar att pruta)\n- **Kai Quag** — Kobaltboss på mellannivå. Ordnar beskydd åt Kobalts smugglarfärder och träffar tänkbara kunder i Lyan. (försiktig, charmerande, självsäker)",
   "en": "The Maelstrom pirates have made a station out of derelict freighters, cargo containers, and stolen scrap metal. They call this home “the Cove.” Enterprising individuals can discover where it is located if they have the tenacity or contacts—though it moves about within the Ashtari Cloud. Only the best friends of pirates might be granted storm drives to better navigate with.\n\n**Notables**\n\n- **Ryle** — A larger-than-life figure with a hatred for the Hegemony. Tough and violent, she enforces a pirate code on those who would follow her. Once stranded her first lieutenant on a barren world for mutiny. (proud, demanding, honorable)\n- **Praxis Ivanov** — Merchant always willing to make a deal. His tentacles are tattooed with the story of his several-hundredyear life. (xeno, experienced, shrewd, loves to barter)\n- **Kai Quag** — Mid-level Cobalt boss. Arranges protection for Cobalt smuggling runs and meets with potential clients at the Cove. (cautious, charming, confident)"
  }
 },
 "body.vos": {
  "blurb": {
   "sv": "Tungt beväpnad, permanent blockad ute i rymden, med skepp som väntar på klartecken. Släta väggar av tät kolbrick, fönster som vetter ut mot den svarta ytan. Diamantärrade, sotiga gruvarbetare som dricker med skakiga händer intill sina klumpiga ultraljudsborrar. Prydliga butiker i besökarnas bosättning.",
   "en": "Well-armed, permanent blockade in space, with ships waiting for clearance. Smooth walls of dense carbon brick, windows looking out onto the black surface. Diamondscarred and sooty-faced miners, drinking with shaking hands by their bulky sonic cutters. Pristine shops of the visitor settlement."
  },
  "details": {
   "sv": "Känd i hela Procyon under smeknamnet ”Glimmer” är den här väldiga planetens yta gjord av kolföreningar som grafit och diamant. Om natten lyser de största kristallformationerna med ett överjordiskt sken — en egenskap många av kristallerna behåller även efter att de slipats. Man måste lägga till vid gillestationen IA-23 i omloppsbana och ta skytteln ned för att göra affärer på ytan.\n\n**Anmärkningsvärda personer**\n\n- **Morek och Ra-na** — Den mest fruktade prisjägaren i Procyon. Ra-na, hans AI-kompanjon, styr hans artefaktskepp och sköter ledningen under jakterna genom den sällsamma rustning han bär. Betald att jaga var och en som plundrar Vos. (skoningslös, vaksam, befallande)\n- **Impera Evazan** — Högt uppsatt logistikofficer i gillet, ansvarig för kristallbrytningen. Invigd i stora delar av gillets försörjningsstruktur. (populär, krävande, slug)\n- **Yola Sprekk** — Juvelerare känd för att utnyttja de unika egenskaperna hos Vos kristaller. Hennes skapelser är kanske det mest konstfärdiga som finns i Procyon. Ett Sprekk-smycke kan öppna dörrar i de mest exklusiva kretsar. (konstnärlig, charmerande, stolt)",
   "en": "Known throughout Procyon by its nickname “Glimmer­,” the surface of this enormous planet is made of carbon compounds such as graphite and diamond. At night, the largest crystal formations glow with unearthly light—a property many of the crystals retain after being cut. One must dock at Guild station IA-23 in orbit and shuttle down to do business on the surface.\n\n**Notables**\n\n- **Morek and Ra-na** — Most-feared bounty hunter in Procyon. Ra-na, his AI partner, helms his artifact ship and runs ops on his hunts via the strange armor he wears. On retainer to hunt any who loot Vos. (ruthless, vigilant, commanding)\n- **Impera Evazan** — High-ranking G u i l d l o g i s t i c s o f f i c e r, responsible for crystal mining. Privy to much of the Guild’s supply structure. (popular, demanding, shrewd)\n- **Yola Sprekk** — Jeweler known for using the unique properties of Vos crystals. Her creations may be the most artful pieces in Procyon. A Sprekk piece can open doors in the most elite circles. (artistic, charming, proud)"
  }
 },
 "body.warren": {
  "blurb": {
   "sv": "En sjudande gatumarknad med neonskyltar som utlovar mat av alla de slag på ett halvdussin språk. Svävarbilar som strömmar mellan tornhöga byggnader. Basen från en källarklubb som spelar senaste mixen; gäster som raglar ut på gatan och sjunger. Societeten på gala i guvernörens palats.",
   "en": "A bustling street market with neon signs promising foods of all kinds in several languages. Hovercars streaming between towering buildings. The bass beat of a basement club playing the latest mix; patrons stumbling onto the street, singing. Socialites attending a gala at the Governor’s mansion."
  },
  "details": {
   "sv": "Grytet är en av Alephs månar och hem åt en ekumenopolis — en stad som täcker hela månens yta. Det är systemets huvudstad, och systemets guvernör Ritam al-Malklä har sin residens här. På Grytet hittar du allt du behöver — mot rätt pris. Skyskraporna är fulla av hederliga affärer; på gatorna görs affärer av betydligt mindre hederligt slag.\n\n**Anmärkningsvärda personer**\n\n- **Ritam al-Malklä** — Guvernör över Rinsystemet, i onåd inom Hus Malklä. Han söker förbättra sin ställning i huset genom att komma över olagliga Ur-artefakter. (kallsinnig, ärelysten, underlig)\n- **Liara Uria** — Ägare till och innehavare av Lock Luna, den ökändaste baren i understaden. (listig, obeveklig, populär)\n- **Rocco Apple** — Skeppskonstruktör utan like. Bygger bara ett exemplar av varje skepp han ritar. (konstnärlig, briljant, reserverad)\n- **Pasha Qu’Olin** — En gång en fruktad lönnmördare bland Knivarna, numera syndikatsledare. Älskar god mat och grophugg. (illmarig, satt, snobbigt klädd, dekadent)",
   "en": "Warren is one of the moons of Aleph and the home to an ecumenopolis—a city spanning the entire surface of the moon. It’s the capitol for the system, and the system Governor Ritam al’Malklaith makes his residence here. On Warren, you can find anything you need—for a price. Its high-rises are full of legitimate business dealings, and its streets far less so.\n\n**Notables**\n\n- **Ritam al’Malklaith** — Governor of the Rin system, in disgrace within House Malklaith. He seeks to improve his position in the House by acquiring illegal Ur artifacts. (callous, ambitious, strange)\n- **Liara Uria** — Owner and operator of the Lock Luna, the most infamous bar in the undercity. (cunning, unforgiving, popular)\n- **Rocco Apple** — Ship designer extraordinaire. Only makes one of each ship designed. (artistic, brilliant, aloof)\n- **Pasha Qu’Olin** — Once a feared assassin among the Knives, now a Syndicate leader. Loves good food and pit fights. (sly, corpulent, sartorial, decadent)"
  }
 }
};
